/**
 * gitpush.js
 *
 * Custom git commit + push endpoint for the Node-RED editor toolbar button.
 * Does NOT require the Node-RED Projects feature to be enabled in settings.
 *
 * Route: POST /gitpush
 * Body:  { "message": "...", "tabId": "...", "branch": "..." }
 *
 * Design:
 *   - Each branch gets its own dedicated git repo under userDir/.flow-repos/<branch>/
 *     so every branch has a completely independent commit history.
 *   - Only the active tab's flow nodes are written to flow.json — all other flows
 *     are excluded from the commit.
 *   - No --force push. Commits are appended cleanly to the branch history.
 *
 * Branch resolution priority:
 *   1. process.env.GIT_BRANCH  (set at server startup)
 *   2. Node-RED Global env var  (User Settings → Environment → GIT_BRANCH)
 *   3. Flow tab env var         (tab Properties → Environment Variables → GIT_BRANCH)
 *   4. Sanitised tab label      (fallback from browser)
 */

var fs = require('fs');
var spawn = require('child_process').spawn;
var path = require('path');
var os = require('os');
var log = require('@node-red/util').log;

var userDir;
var runtimeAPI;

/**
 * Run a single git command using spawn (avoids shell injection).
 * @param {string[]} args - git argument array e.g. ['commit', '-m', 'msg']
 * @param {string}   cwd  - working directory
 * @returns {Promise<string>} stdout on success, rejects with { code, stderr, stdout }
 */
function runGit(args, cwd) {
    return new Promise(function(resolve, reject) {
        var proc = spawn('git', args, { cwd: cwd });
        var stdout = '';
        var stderr = '';
        proc.stdout.on('data', function(d) { stdout += d.toString(); });
        proc.stderr.on('data', function(d) { stderr += d.toString(); });
        proc.on('close', function(code) {
            if (code !== 0) {
                reject({ code: code, stderr: stderr, stdout: stdout });
            } else {
                resolve(stdout);
            }
        });
        proc.on('error', function(err) {
            reject({ code: -1, stderr: err.message, stdout: '' });
        });
    });
}

/**
 * Branch resolution priority:
 *   1. process.env.GIT_BRANCH   — set at server startup (e.g. GIT_BRANCH=main node ...)
 *   2. Node-RED Global env var  — User Settings → Environment → GIT_BRANCH
 *   3. Flow tab env var         — tab Properties → Environment Variables → GIT_BRANCH
 *   4. Fallback                 — sanitised tab label from the browser
 */
function getFlowAndBranch(tabId, fallbackBranch, req) {

    // --- Priority 1: process.env.GIT_BRANCH (set at server startup) ---
    var processBranch = null;
    if (process.env.GIT_BRANCH && process.env.GIT_BRANCH.trim().length > 0) {
        processBranch = process.env.GIT_BRANCH.trim().replace(/[^a-zA-Z0-9\-\/]/g, '').substring(0, 100);
    }

    // If process env is already set, no need to call runtimeAPI
    if (processBranch) {
        log.trace('[gitpush] Branch → process env: ' + processBranch);
        if (tabId && runtimeAPI) {
            // Still need to fetch activeFlow so we have the flow data for the commit
            return runtimeAPI.flows.getFlow({ id: tabId, user: null, req: null })
                .then(function(flow) { return { branch: processBranch, flow: flow }; })
                .catch(function() { return { branch: processBranch, flow: null }; });
        }
        return Promise.resolve({ branch: processBranch, flow: null });
    }

    if (!runtimeAPI) {
        return Promise.resolve({ branch: fallbackBranch, flow: null });
    }

    // Fetch all flows (for global-config node) and active flow tab in parallel
    var allFlowsPromise = runtimeAPI.flows.getFlows({ user: null, req: null })
        .catch(function() { return null; });
    var activeFlowPromise = tabId
        ? runtimeAPI.flows.getFlow({ id: tabId, user: null, req: null }).catch(function() { return null; })
        : Promise.resolve(null);

    return Promise.all([allFlowsPromise, activeFlowPromise])
        .then(function(results) {
            var allFlows  = results[0];
            var activeFlow = results[1];
            var branch = null;

            // --- Priority 2: Node-RED Global env var (User Settings → Environment UI) ---
            // Stored as the single global-config node in the flows array
            if (allFlows && Array.isArray(allFlows.flows)) {
                for (var i = 0; i < allFlows.flows.length; i++) {
                    if (allFlows.flows[i].type === 'global-config') {
                        var globalNode = allFlows.flows[i];
                        if (Array.isArray(globalNode.env)) {
                            var ge = globalNode.env.find(function(e) { return e.name.trim() === 'GIT_BRANCH'; });
                            if (ge && ge.value && ge.value.trim().length > 0) {
                                branch = ge.value.trim().replace(/[^a-zA-Z0-9\-\/]/g, '').substring(0, 100);
                                log.trace('[gitpush] Branch → global config env: ' + branch);
                            }
                        }
                        break;
                    }
                }
            }

            // --- Priority 3: Flow tab env var ---
            if (!branch && activeFlow && Array.isArray(activeFlow.env)) {
                var fe = activeFlow.env.find(function(e) { return e.name.trim() === 'GIT_BRANCH'; });
                if (fe && fe.value && fe.value.trim().length > 0) {
                    branch = fe.value.trim().replace(/[^a-zA-Z0-9\-\/]/g, '').substring(0, 100);
                    log.trace('[gitpush] Branch → flow env: ' + branch);
                }
            }

            // --- Priority 4: fallback (sanitised tab label) ---
            if (!branch) {
                branch = fallbackBranch;
                log.trace('[gitpush] Branch → fallback: ' + branch);
            }

            return { branch: branch, flow: activeFlow };
        });
}

/**
 * Return the directory for a branch's dedicated git repo.
 * Stored at: userDir/.flow-repos/<sanitised-branch>/
 */
function getFlowRepoDir(branch) {
    var safeName = branch.replace(/\//g, '-').replace(/[^a-zA-Z0-9\-]/g, '').substring(0, 100);
    return path.join(userDir, '.flow-repos', safeName);
}

/**
 * Get the remote origin URL from the main userDir git repo so the per-flow
 * repos can push to the same remote.
 */
function getRemoteUrl() {
    return runGit(['remote', 'get-url', 'origin'], userDir)
        .then(function(url) { return url.trim(); });
}

/**
 * Ensure the per-flow git repo for a branch is initialised.
 *
 * First call  : creates the directory, inits a repo, sets the remote, and
 *               bootstraps from the remote branch if it already exists so we
 *               append to its history rather than starting over.
 * Subsequent  : no-op (the .git directory already exists).
 */
function ensureFlowRepo(flowDir, remoteUrl, branch) {
    var gitDir = path.join(flowDir, '.git');
    var repoExists = false;
    try { fs.statSync(gitDir); repoExists = true; } catch(e) {}
    if (repoExists) {
        return Promise.resolve();
    }

    try { fs.mkdirSync(flowDir, { recursive: true }); } catch(e) {}

    return runGit(['init'], flowDir)
        .then(function() { return runGit(['remote', 'add', 'origin', remoteUrl], flowDir); })
        .then(function() { return runGit(['config', 'user.email', 'nodered@localhost'], flowDir); })
        .then(function() { return runGit(['config', 'user.name', 'Node-RED'], flowDir); })
        .then(function() {
            // If the remote branch already has commits, fetch them so subsequent
            // pushes are fast-forward (no force needed).
            return runGit(['fetch', '--depth=50', 'origin', branch], flowDir)
                .then(function() {
                    return runGit(['reset', '--hard', 'FETCH_HEAD'], flowDir);
                })
                .catch(function() {
                    // Remote branch doesn't exist yet — first push will create it.
                    log.trace('[gitpush] Remote branch ' + branch + ' is new, will be created on first push');
                });
        });
}

module.exports = {
    init: function(settings, _runtimeAPI) {
        userDir = settings.userDir || path.join(os.homedir(), '.node-red');
        runtimeAPI = _runtimeAPI;
        log.trace('[gitpush] userDir resolved to: ' + userDir);
    },

    post: function(req, res) {
        var message = 'Node-RED flow update';
        if (req.body && typeof req.body.message === 'string' && req.body.message.trim().length > 0) {
            message = req.body.message.trim().substring(0, 500);
        }

        var tabId = (req.body && typeof req.body.tabId === 'string') ? req.body.tabId.trim() : '';

        var fallbackBranch = 'flows';
        if (req.body && typeof req.body.branch === 'string' && req.body.branch.trim().length > 0) {
            fallbackBranch = req.body.branch.trim().replace(/[^a-zA-Z0-9\-\/]/g, '').substring(0, 100);
        }

        // Run getFlowAndBranch and getRemoteUrl in parallel
        Promise.all([
            getFlowAndBranch(tabId, fallbackBranch, req),
            getRemoteUrl()
        ])
        .then(function(results) {
            var branch    = results[0].branch;
            var flowData  = results[0].flow;
            var remoteUrl = results[1];

            if (!flowData) {
                return res.status(400).json({ error: 'Could not retrieve flow data for tab: ' + tabId });
            }

            var flowDir = getFlowRepoDir(branch);
            log.trace('[gitpush] Starting push — branch: ' + branch + ' repo: ' + flowDir + ' message: ' + message);

            return ensureFlowRepo(flowDir, remoteUrl, branch)
                .then(function() {
                    // Write only the active flow's nodes to flow.json in its dedicated repo
                    fs.writeFileSync(path.join(flowDir, 'flow.json'), JSON.stringify(flowData, null, 2), 'utf8');
                    return runGit(['add', 'flow.json'], flowDir);
                })
                .then(function() {
                    return runGit(['commit', '-m', message], flowDir);
                })
                .then(function(commitOut) {
                    // Push without --force — appends to history, never rewrites it.
                    // HEAD:<branch> creates the remote branch if it doesn't exist yet.
                    return runGit(['push', 'origin', 'HEAD:' + branch], flowDir)
                        .then(function(pushOut) {
                            log.trace('[gitpush] Push succeeded to origin/' + branch);
                            res.status(200).json({ success: true, branch: branch, output: commitOut + pushOut });
                        });
                })
                .catch(function(err) {
                    // "nothing to commit" — flow.json unchanged since last commit
                    if (err.stdout && err.stdout.indexOf('nothing to commit') !== -1) {
                        log.trace('[gitpush] Nothing to commit for branch ' + branch);
                        res.status(200).json({ success: true, branch: branch, output: 'Nothing to commit. Already up to date.' });
                        return;
                    }
                    log.warn('[gitpush] Git error (code ' + (err.code || '?') + '): ' + err.stderr);
                    res.status(500).json({ error: err.stderr || 'git operation failed' });
                });
        })
        .catch(function(err) {
            log.warn('[gitpush] Unexpected error: ' + (err.message || err));
            res.status(500).json({ error: err.message || 'Internal error' });
        });
    }
};
